MultiLanguageSpellData['tw'][1214688] = {name = "煙火", additional_info = "300 碼範圍\n瞬發\n[q]里克的舞台助手將煙火投入場中，對命中位置2.5碼範圍內的玩家造成6708070點火焰傷害。\n\n 煙火會散播燃燒的火花，對命中位置2.5碼範圍內的玩家造成6708070點火焰傷害。\n\n 煙火遭受攻擊時提供 刺激 。"}
MultiLanguageSpellData['tw'][1214689] = {name = "電氣充能武器", additional_info = "無限範圍\n瞬發\n[q]布萊恩的裝備獲得尖端科技升級的強化\n\n電氣充能盾牌\n 對布萊恩的有效治療效果會產生脈動，對附近敵人造成自然傷害。\n\n電氣充能手槍\n 每次射擊都會釋放電流，跳向附近敵人，並降低其攻擊速度。治療布萊恩會對手槍進行超級充能，可造成更多傷害。\n\n電氣充能獵槍\n 每次命中敵人，都有一定機率將其擊倒。治療布萊恩會對獵槍進行超級充能，可造成更多傷害。"}
